UPDATE wms_inventory_freeze
freeze_no = #{freezeNo}, warehouse_id = #{warehouseId}, location_id = #{locationId}, product_id = #{productId}, batch_no = #{batchNo}, freeze_type = #{freezeType}, freeze_reason = #{freezeReason}, freeze_quantity = #{freezeQuantity}, unit = #{unit}, freeze_time = #{freezeTime}, freeze_operator = #{freezeOperator}, unfreeze_time = #{unfreezeTime}, unfreeze_operator = #{unfreezeOperator}, unfreeze_reason = #{unfreezeReason}, status = #{status}, business_no = #{businessNo}, remark = #{remark}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT

FROM wms_inventory_freeze if
LEFT JOIN wms_product p ON if.product_id = p.id
LEFT JOIN wms_location l ON if.location_id = l.id

    AND if.freeze_type = #{freezeType}
    AND if.status = #{status}
    AND if.warehouse_id = #{warehouseId}
    AND if.product_id = #{productId}
    AND if.batch_no LIKE CONCAT('%', #{batchNo}, '%')

ORDER BY if.freeze_time DESC

    LIMIT #{query.pageNum}, #{query.pageSize}
